import{_ as e,C as r,o as a,c as n,aj as o,E as s}from"./framework.js";const p=JSON.parse('{"title":"文件 | Cms / Content | Documentation","description":"文件管理站点 CMS 文件库：可上传 PDF、ZIP、文档等，按文件夹组织，并可通过站点 URL 对外提供下载或访问。与顶栏 媒体库（图片等媒体、k.media）不是同一套存储。","frontmatter":{"title":"文件 | Cms / Content | Documentation","description":"文件管理站点 CMS 文件库：可上传 PDF、ZIP、文档等，按文件夹组织，并可通过站点 URL 对外提供下载或访问。与顶栏 媒体库（图片等媒体、k.media）不是同一套存储。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/content/files.html"}]]},"headers":[],"relativePath":"zh/cms/content/files.md","filePath":"cms/content/files.md","lastUpdated":1780295080000}'),l={name:"zh/cms/content/files.md"};function i(c,t,h,g,b,m){const d=r("DocImage");return a(),n("div",null,[t[0]||(t[0]=o('<h1 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to &quot;文件&quot;">​</a></h1><blockquote><p>菜单：<strong>内容 → 文件</strong>（须在后台 <strong>&quot;编辑菜单&quot;</strong> 中勾选显示；路由 <code>advanced: true</code>）<br> 深链：<code>/_Admin/content/files?SiteId={站点GUID}</code><br> 常见查询参数：<code>folder</code>（当前路径，默认 <code>/</code>）、<code>keyword</code>（搜索词）、<code>provider</code>（存储提供方，默认 <code>default</code>）</p></blockquote><p><strong>文件</strong>管理站点 <strong>CMS 文件库</strong>：可上传 PDF、ZIP、文档等，按文件夹组织，并可通过站点 <strong>URL</strong> 对外提供下载或访问。与顶栏 <strong><a href="/kb-docs/zh/cms/site/media.html">媒体库</a></strong>（图片等媒体、<code>k.media</code>）不是同一套存储。</p><div class="warning custom-block"><p class="custom-block-title">与 k.file 不是一回事</p><table tabindex="0"><thead><tr><th></th><th><strong>内容 → 文件</strong>（本页）</th><th><strong><a href="/kb-docs/zh/api/file/file.html">k.file</a></strong></th></tr></thead><tbody><tr><td>用途</td><td>后台可视化管理、可路由的 CMS 文件</td><td>KScript 读写站点磁盘上的文件</td></tr><tr><td>后台界面</td><td><strong>有</strong>（本页）</td><td><strong>无</strong> 专用可视化界面</td></tr><tr><td>脚本 API</td><td>目前 <strong>没有</strong> 对应的 <code>k.xxx</code> 操作本库文件</td><td><code>k.file.read</code> / <code>write</code> 等</td></tr></tbody></table><p>勿把本页当成 <code>k.file</code> 的管理入口；在内容条目里选中的「文件」字段值，指向的也是 <strong>本 CMS 文件库</strong> 中的资源，而不是 <code>k.file</code> 路径。</p></div><div class="tip custom-block"><p class="custom-block-title">图片放哪里？</p><p>界面提示：网站展示用的 <strong>图片、图标</strong> 建议放在 <strong>媒体库</strong>；本页适合附件、可下载文档等 <strong>非图片为主</strong> 的站点文件。</p></div><div class="tip custom-block"><p class="custom-block-title">如何看到本菜单</p><p>若左侧 <strong>内容</strong> 下没有 <strong>文件</strong>，请点击后台 <strong>编辑菜单</strong>（<code>editMenu</code>，用于显示/隐藏不常用菜单项），勾选 <strong>文件</strong> 后保存。详见 <a href="./../navigation.html#权限与高级菜单">菜单总览 · 权限与高级菜单</a>。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>进入站点后台（<code>SiteId</code> 在地址栏）。</li><li>在 <strong>编辑菜单</strong> 中启用 <strong>文件</strong> 后，左侧 <strong>内容 → 文件</strong>。</li><li>进入子文件夹或搜索时，地址栏会同步 <code>folder</code>、<code>keyword</code>、<code>provider</code>。</li></ol>',8)),s(d,{src:"/cms/content/files-list.png",alt:"内容 · 文件列表",width:"1120"}),t[1]||(t[1]=o('<h2 id="界面说明" tabindex="-1">界面说明 <a class="header-anchor" href="#界面说明" aria-label="Permalink to &quot;界面说明&quot;">​</a></h2><h3 id="面包屑" tabindex="-1">面包屑 <a class="header-anchor" href="#面包屑" aria-label="Permalink to &quot;面包屑&quot;">​</a></h3><p>顶部路径从 <strong>文件</strong>（根）到当前文件夹，点击可跳转上级。</p><h3 id="工具栏" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏" aria-label="Permalink to &quot;工具栏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>全选</td><td>选中当前页列出的文件与文件夹</td></tr><tr><td>上传</td><td>向 <strong>当前文件夹</strong> 上传一个或多个文件；<strong>搜索状态下不可用</strong></td></tr><tr><td>新建文件夹</td><td>在当前路径下创建子文件夹；搜索状态下不可用</td></tr><tr><td>下载</td><td>勾选后打包下载选中文件/文件夹</td></tr><tr><td>删除</td><td>勾选后批量删除（权限 <code>file</code> · <code>delete</code>）</td></tr><tr><td>搜索 / 提供方</td><td>右侧按关键词搜索；若站点配置了多个 <strong>提供方</strong>，可切换 Tab（<code>provider</code>）</td></tr></tbody></table><p>单文件大小上限约 <strong>150 MB</strong>（超出会提示）。若目标路径已存在同名文件，上传前会提示是否覆盖。</p><h3 id="列表列" tabindex="-1">列表列 <a class="header-anchor" href="#列表列" aria-label="Permalink to &quot;列表列&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td>文件名</td><td>文件或文件夹名称；点击文件夹进入子目录</td></tr><tr><td>URL</td><td>该文件在站点下的访问路径（可复制，用于页面链接或内容字段）</td></tr><tr><td>引用</td><td>被哪些站点资源引用（若有）</td></tr><tr><td>大小</td><td>文件体积</td></tr><tr><td>最后修改</td><td>更新时间</td></tr><tr><td>行内操作</td><td><strong>打开所在文件夹</strong>、<strong>复制 URL</strong>、<strong>预览</strong>（适用时）、<strong>下载</strong></td></tr></tbody></table><p>列表底部分页；部分提供方支持 <strong>无限滚动</strong> 加载更多（以接口返回为准）。</p><h2 id="典型用法" tabindex="-1">典型用法 <a class="header-anchor" href="#典型用法" aria-label="Permalink to &quot;典型用法&quot;">​</a></h2><h3 id="上传可下载附件" tabindex="-1">上传可下载附件 <a class="header-anchor" href="#上传可下载附件" aria-label="Permalink to &quot;上传可下载附件&quot;">​</a></h3><ol><li><strong>内容 → 文件</strong>，进入目标文件夹（如 <code>/downloads</code>）。</li><li><strong>上传</strong> 选择本地 PDF/ZIP 等。</li><li>复制列表中的 <strong>URL</strong>，在页面 HTML、富文本或模板中作为链接地址使用（由站点路由按 CmsFile 输出文件内容）。</li></ol><h3 id="在内容字段中选择文件" tabindex="-1">在内容字段中选择文件 <a class="header-anchor" href="#在内容字段中选择文件" aria-label="Permalink to &quot;在内容字段中选择文件&quot;">​</a></h3><p><a href="./content-types.html">数据类型</a> 中字段控件为 <strong>文件</strong>（可勾选 <strong>启用多个</strong>）时，录入界面 <strong>选择文件</strong> 会打开与本页相同的浏览对话框（<code>KFileDialog</code>），选中后把该 CMS 文件的 <strong>URL/键</strong> 写入内容条目。</p><h3 id="与媒体库对比" tabindex="-1">与媒体库对比 <a class="header-anchor" href="#与媒体库对比" aria-label="Permalink to &quot;与媒体库对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th><strong>文件</strong>（本页，CmsFile）</th><th><strong>媒体库</strong></th></tr></thead><tbody><tr><td>菜单</td><td>内容 → 文件</td><td>顶栏媒体库</td></tr><tr><td>典型内容</td><td>PDF、ZIP、附件</td><td>图片、展示用媒体</td></tr><tr><td>内容字段</td><td>控件 <strong>文件</strong></td><td>控件 <strong>图片</strong> / <strong>高级图片</strong></td></tr><tr><td>脚本</td><td>暂无专用 <code>k.xxx</code></td><td><code>k.media</code></td></tr></tbody></table><h2 id="开发说明" tabindex="-1">开发说明 <a class="header-anchor" href="#开发说明" aria-label="Permalink to &quot;开发说明&quot;">​</a></h2><ul><li>需要 <strong>脚本读写磁盘文件</strong>（日志、导入临时文件等）时，使用 <a href="/kb-docs/zh/api/file/file.html">k.file</a>，与本文后台 <strong>内容 → 文件</strong> 无关。</li><li>CMS 文件库文件的对外访问，一般通过复制后台列表中的 <strong>URL</strong> 或前台路由访问，不以 <code>k.file</code> 路径为准。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="/kb-docs/zh/cms/site/media.html">媒体库</a></td><td>图片与媒体</td></tr><tr><td><a href="./content-types.html">数据类型</a></td><td>「文件」字段控件</td></tr><tr><td><a href="/kb-docs/zh/api/file/file.html">k.file</a></td><td>磁盘文件 KScript API（非本页）</td></tr><tr><td><a href="./">内容模块概述</a></td><td>内容分组菜单</td></tr></tbody></table>',20))])}const u=e(l,[["render",i]]);export{p as __pageData,u as default};
